    if (!s) return;
    const trimmed = s.trim();
    if (trimmed.length >= MIN_MATCH_LENGTH) out.add(trimmed);
  };

  add(value);
  if (kind === "name") {
    const tokens = value.trim().split(/\s+/).filter(Boolean);
